def get_grids(text, n):
 def block(label):
  m=re.search(rf'Demo pair {n} {label} \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)',text)
  h,w=map(int,m.group(1,2)); rows=[list(map(int,line.split())) for line in m.group(3).splitlines()[:h]]
  assert len(rows)==h and all(len(r)==w for r in rows),(n,label,h,w,[len(r) for r in rows])
  return rows
 return block('input'),block('output')
