def transform(grid):
 h,w=len(grid),len(grid[0])
 from collections import Counter,deque
 bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
 seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    rr,cc=q.pop(); comp.append((rr,cc))
    for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
     if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]!=bg:
      seen.add((nr,nc)); q.append((nr,nc))
   comps.append(comp)
 src=max(comps,key=len)
 r0=min(r for r,c in src); r1=max(r for r,c in src)
 c0=min(c for r,c in src); c1=max(c for r,c in src)
 pattern=[[(r,c,grid[r][c]) for c in range(c0,c1+1)] for r in range(r0,r1+1)]
 ar=(r0+r1)//2; ac=(c0+c1)//2
 out=[row[:] for row in grid]
 for comp in comps:
  if comp is src: continue
  # each separate component is one target
  tr,tc=comp[0]
  for dr,row in enumerate(pattern):
   for dc,cell in enumerate(row):
    rr=tr+dr-(ar-r0); cc=tc+dc-(ac-c0)
    if 0<=rr<h and 0<=cc<w and cell[2]!=bg:
     out[rr][cc]=cell[2]
 return out
